# shipping cost (dollars) by package weight (ounces)
for weight in range(4, 80, 15):
    if weight <= 8:
        cost = 4
    elif weight <= 16:
        cost = 6
    elif weight <= 48:
        cost = 6 + (weight - 16) // 8
    else:
        cost = 12
    print(cost)

# every third house on the block: odd numbers on the left side
left = right = 0
for house in range(1, 30, 3):
    if house % 2 == 0:
        right += 1
    else:
        left += 1
print(left)
print(right)
print(left == right)

for trial in range(2):
    if trial == 0:
        word = "level"
    else:
        word = "lever"
    n = len(word)
    i = 0
    same = True
    while i < n // 2:
        if word[i] != word[n - 1 - i]:
            same = False
            break
        i += 1
    if same:
        print(word, "reads the same both ways")
    else:
        print(word, "is not a palindrome (" + word[i] + " vs " + word[n - 1 - i] + ")")
